import java.util.*;

class Codec {
  // left child = first child, right child = next sibling
  public TreeNode encode(Node root) {
    if (root == null) return null;
    TreeNode node = new TreeNode(root.val);
    if (root.children != null && !root.children.isEmpty()) {
      node.left = encode(root.children.get(0));
      TreeNode cur = node.left;
      for (int i = 1; i < root.children.size(); i++) {
        cur.right = encode(root.children.get(i));
        cur = cur.right;
      }
    }
    return node;
  }

  public Node decode(TreeNode root) {
    if (root == null) return null;
    Node node = new Node(root.val, new ArrayList<>());
    for (TreeNode child = root.left; child != null; child = child.right) node.children.add(decode(child));
    return node;
  }
}
